            node.put\("body",    t.getOrDefault\("body",    ""\)\);
            node.put\("headers", t.getOrDefault\("headers", ""\)\);
        }

        try {
            mapper.writeValue\(file, root\);
        } catch \(IOException e\) {
            throw new RuntimeException\("Failed to save http.toml", e\);
        }
    }

